  + approved_by_head_doctor : boolean
}

class Treatment {
  + stage : int
}

class ConsentForm {}

Patient "1" -- "*" Diagnosis : assigned to
Doctor "1..*" -- "*" Patient : treats
Doctor "1" -- "*" Diagnosis : makes
Doctor "1" -- "*" Treatment : downgrades
Nurse "1..*" -- "*" Treatment : checks
Doctor "1..*" -- "*" Nurse : works with
Doctor "1" -- "1" HospitalHouseMD : head of
HospitalHouseMD "1" -- "*" Illness : has database of
HospitalHouseMD "1" -- "*" Diagnosis : manages
Diagnosis "1" -- "*" Treatment : results in
Illness "1" -- "*" Diagnosis : causes
Treatment "0..*" -- "1" Diagnosis : for
Patient "1" -- "0..*" ConsentForm : signs
ConsentForm "1" -- "1" Patient : belongs to
Treatment "0..*" -- "1" Patient : applied to

@enduml

